export const tasksFor=(key,tier='Higher')=>endocrineTasks[key].filter(t=>!t.higher||tier==='Higher');
export const validEndo=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];
export const advanceEndo=(route,step,choice)=>Number.isInteger(step)&&step>=0&&step<route.length&&route[step]===choice?step+1:step;
export const numericEndo=(value,target)=>value!==''&&value!==null&&value!==undefined&&Number.isFinite(Number(value))&&Math.abs(Number(value)-target)<.001;
export function glucoseState({progress=0,mode='insulin',active=true}={}){let t=Math.max(0,Math.min(1,Number(progress)||0)),n=active?Math.floor(t*6):0,fraction=active?(t*6-n):0,inTransit=fraction>1e-8?1:0;return mode==='glucagon'?{blood:2+n,store:8-n-inTransit,transferred:n,inTransit,fraction}:{blood:8-n-inTransit,store:2+n,transferred:n,inTransit,fraction};}
export const temperatureState=condition=>({dilated:condition==='hot',sweat:condition==='hot',shivering:condition==='cold'});
